parameters.jsCode:
const metrics = JSON.parse($input.item.json.stdout);
const data_op_ref = metrics.data_op_ref;

// data_op_ref hariç tüm parametreleri al
const excludeKeys = ['data_op_ref'];
const result = [];

for (const [key, value] of Object.entries(metrics)) {
  if (!excludeKeys.includes(key)) {
    result.push({
      data_op_ref: data_op_ref,
      parameter: key,
      value: value
    });
  }
}

return result.map(item => ({ json: item }));

parameters.query:
SELECT r.*
  FROM reads r
 WHERE r.conversion_ref = {{ $('Resolve Conversion Ref').item.json.conversion_ref }}
   AND NOT EXISTS (
     SELECT 1
       FROM data_operations dop
      WHERE dop.read_ref = r.uniqueref
        AND dop.recipe_ref = 6
        AND dop.status_concept_ref = 29
   );

parameters.jsCode:
const kitBedMap = {
  "1":  "CES_v3_hg38_original_normalized_chr.bed",
  "2":  "CHCS_C_v2_target_hg38_liftover_normalized_chr.bed",
  "40": "Twist_Exome_hg38_original_normalized_chr.bed",
  "73": "HCS_v2_0_1_hg38_target_normalized.bed",
  "97": "Twist_Exome_hg38_original_with_mtDNA_normalized_chr.bed"
};
const items = $("Get Reads").all();
return items.map((item, idx) => ({
  json: {
    ...item.json,
    bed_file_path: kitBedMap[String(item.json.kit_ref)] || ""
  },
  pairedItem: { item: idx }
}));

parameters.command:
={{ $('Loop Samples').item.json.lane == 0 ? 
   `fdfind "${$('Loop Samples').item.json.sample_id}_" ${$('Find Conversion Path').item.json.stdout}` : 
   `fdfind "${$('Loop Samples').item.json.sample_id}_.*_L00${$('Loop Samples').item.json.lane}_" ${$('Find Conversion Path').item.json.stdout}` 
}}

